   107	// detectScopeBaseRef finds the closest non-self ancestor branch the
   108	// review should be scoped against. Strategy:
   109	//
   110	//  1. Find local + remote branches whose tips are ancestors of HEAD
   111	//     (i.e., branches the current branch is descended from). Exclude
   112	//     the current branch itself.
   113	//  2. Pick the one with the most recent commit timestamp at its tip.
   114	//     This handles stacked PRs where a feature branches off another
   115	//     feature: prefer the immediate parent over a more distant one.
   116	//  3. Fallback chain when no ancestor is found:
   117	//     origin/HEAD → origin/main → origin/master → main → master
   118	//  4. If none of those exist either, return an error.
   119	//
   120	// Returns the ref name (e.g., "main", "origin/main", "feat/parent")
   121	// suitable for use in `git diff <ref>...HEAD`.
   122	func detectScopeBaseRef(ctx context.Context, repo *git.Repository) (string, error) {
   123		head, err := repo.Head()
   124		if err != nil {
   125			return fallbackScopeRef(repo)
   126		}
   127		headHash := head.Hash()
   128	
   129		// Determine the current branch's symbolic ref name (empty for detached HEAD).
   130		currentBranchShort := ""
   131		if head.Name().IsBranch() {
   132			currentBranchShort = head.Name().Short() // e.g. "feat/x"
   133		}
   134	
   135		repoRoot, rootErr := repoWorktreePath(repo)
   136		if rootErr != nil {
   137			return fallbackScopeRef(repo)
   138		}
   139	
   140		// Enumerate ancestor branches in a single git invocation. for-each-ref
   141		// --merged HEAD lets git use its commit-graph index to answer "is this
   142		// ref an ancestor of HEAD?" in O(1) per ref via packed reachability
   143		// rather than the previous O(branches × commits) repo.Log walks.
   144		type candidate struct {
   145			name    string
   146			tipUnix int64
   147		}
   148		var candidates []candidate
   149	
   150		out, runErr := runGit(ctx, repoRoot,
   151			"for-each-ref",
   152			"--merged", "HEAD",
   153			"--format=%(refname:short)%09%(committerdate:unix)",
   154			"refs/heads/", "refs/remotes/",
   155		)
   156		if runErr != nil {
   157			// git for-each-ref unavailable or repo state confused — fall back
   158			// to a slow walk via go-git, mirroring the prior behaviour rather
   159			// than failing the review launch.
   160			return slowDetectScopeBaseRef(ctx, repo, headHash, currentBranchShort)
   161		}
   162	
   163		for _, line := range strings.Split(out, "\n") {
   164			if ctx.Err() != nil {
   165				return "", ctx.Err() //nolint:wrapcheck // propagate context cancellation
   166			}
   167			line = strings.TrimSpace(line)
   168			if line == "" {
   169				continue
   170			}
   171			parts := strings.SplitN(line, "\t", 2)
   172			if len(parts) != 2 {
   173				continue
   174			}
   175			name := parts[0]
   176			// Skip the current branch itself (and its full ref form, both shapes
   177			// for-each-ref might emit).
   178			if name == currentBranchShort {
   179				continue
   180			}
   181			// Skip refs that resolve to the same commit as HEAD — same hash,
   182			// different name (e.g. an unmoved freshly-merged feature).
   183			if hash, lookupErr := repo.ResolveRevision(plumbing.Revision(name)); lookupErr == nil && hash != nil && *hash == headHash {
   184				continue
   185			}
   186			unix, parseErr := strconv.ParseInt(parts[1], 10, 64)
   187			if parseErr != nil {
   188				continue
   189			}
   190			candidates = append(candidates, candidate{name: name, tipUnix: unix})
   191		}
