   193		if len(candidates) > 0 {
   194			// Pick the candidate with the most recent tip (closest ancestor).
   195			best := candidates[0]
   196			for _, c := range candidates[1:] {
   197				if c.tipUnix > best.tipUnix {
   198					best = c
   199				}
   200			}
   201			return best.name, nil
   202		}
