   207	// slowDetectScopeBaseRef is the pre-optimization fallback used only when the
   208	// `git for-each-ref --merged` shell-out fails. It walks all refs and checks
   209	// ancestry via repo.Log per ref (O(branches × commits)). Kept as a defense
   210	// against environments where git CLI is unavailable but go-git can still
   211	// resolve refs.
   212	func slowDetectScopeBaseRef(ctx context.Context, repo *git.Repository, headHash plumbing.Hash, currentBranchShort string) (string, error) {
   213		refs, err := repo.References()
   214		if err != nil {
   215			return fallbackScopeRef(repo)
   216		}
   217	
   218		type candidate struct {
   219			name    string
   220			tipTime time.Time
   221		}
   222		var candidates []candidate
   223	
   224		_ = refs.ForEach(func(ref *plumbing.Reference) error { //nolint:errcheck // best-effort search
   225			if ctx.Err() != nil {
   226				return ctx.Err()
   227			}
   228			if !ref.Name().IsBranch() && !ref.Name().IsRemote() {
   229				return nil
   230			}
   231			if ref.Name().Short() == currentBranchShort {
   232				return nil
   233			}
   234			tipHash := ref.Hash()
   235			if tipHash == headHash {
   236				return nil
   237			}
   238			isAnc, ancErr := isAncestorOf(ctx, repo, tipHash, headHash)
   239			if ancErr != nil {
   240				return nil //nolint:nilerr // best-effort: skip unresolvable refs
   241			}
   242			if !isAnc {
   243				return nil
   244			}
   245			commit, cErr := repo.CommitObject(tipHash)
   246			if cErr != nil {
   247				return nil //nolint:nilerr // best-effort: skip refs with no commit object
   248			}
   249			candidates = append(candidates, candidate{
   250				name:    ref.Name().Short(),
   251				tipTime: commit.Committer.When,
   252			})
   253			return nil
   254		})
   255		if ctx.Err() != nil {
   256			return "", ctx.Err() //nolint:wrapcheck // propagate context cancellation
   257		}
   258		if len(candidates) > 0 {
   259			best := candidates[0]
   260			for _, c := range candidates[1:] {
   261				if c.tipTime.After(best.tipTime) {
   262					best = c
   263				}
   264			}
   265			return best.name, nil
   266		}
   267		return fallbackScopeRef(repo)
   268	}
